CREATE TABLE IF NOT EXISTS sync_operations(op_id TEXT PRIMARY KEY,command_hash TEXT NOT NULL,result TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_source_states(state_id TEXT PRIMARY KEY,url TEXT REFERENCES sep_urls,version_id TEXT REFERENCES sep_versions,body_id TEXT REFERENCES sep_contents,availability TEXT NOT NULL,components TEXT NOT NULL,parent_id TEXT REFERENCES sync_source_states);
CREATE TABLE IF NOT EXISTS sync_heads(url TEXT PRIMARY KEY REFERENCES sep_urls,state_id TEXT REFERENCES sync_source_states);
CREATE TABLE IF NOT EXISTS sync_component_epochs(url TEXT REFERENCES sep_urls,component TEXT,epoch INTEGER NOT NULL,PRIMARY KEY(url,component));
CREATE TABLE IF NOT EXISTS sync_evidence(evidence_id TEXT PRIMARY KEY,event_id TEXT REFERENCES events,url TEXT REFERENCES sep_urls,state_id TEXT REFERENCES sync_source_states,field TEXT NOT NULL,quote TEXT,expected TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_decisions(decision_id TEXT PRIMARY KEY,event_id TEXT REFERENCES events,kind TEXT NOT NULL CHECK(kind IN ('ai','operator')),outcome TEXT NOT NULL,payload TEXT NOT NULL,verification TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_decision_state(decision_id TEXT PRIMARY KEY REFERENCES sync_decisions,status TEXT NOT NULL CHECK(status IN ('current','needs_recheck','cancelled','superseded')));
CREATE TABLE IF NOT EXISTS sync_dependencies(decision_id TEXT REFERENCES sync_decisions,evidence_id TEXT REFERENCES sync_evidence,PRIMARY KEY(decision_id,evidence_id));
CREATE TABLE IF NOT EXISTS sync_transitions(transition_id TEXT PRIMARY KEY,op_id TEXT NOT NULL,decision_id TEXT REFERENCES sync_decisions,old_status TEXT NOT NULL,new_status TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_jobs(job_id TEXT PRIMARY KEY,event_id TEXT REFERENCES events,context TEXT NOT NULL,prompt TEXT NOT NULL,cache_key TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_job_evidence(job_id TEXT REFERENCES sync_jobs,evidence_id TEXT REFERENCES sync_evidence,PRIMARY KEY(job_id,evidence_id));
CREATE TABLE IF NOT EXISTS sync_answer_cache(cache_key TEXT PRIMARY KEY,answer TEXT NOT NULL,answer_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_reservations(cache_key TEXT PRIMARY KEY,reservation TEXT NOT NULL,transport_status TEXT NOT NULL CHECK(transport_status IN ('reserved','calling','cached','uncertain')));
CREATE TABLE IF NOT EXISTS sync_validation_memos(validation_key TEXT PRIMARY KEY,decision_id TEXT REFERENCES sync_decisions,outcome TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_adoptions(adoption_id TEXT PRIMARY KEY,decision_id TEXT UNIQUE REFERENCES sync_decisions,event_id TEXT REFERENCES events,change_id INTEGER UNIQUE REFERENCES changes,cancelled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sync_links(event_id TEXT REFERENCES events,version_id TEXT REFERENCES sep_versions,is_current INTEGER NOT NULL,PRIMARY KEY(event_id,version_id));
CREATE TABLE IF NOT EXISTS sync_event_epochs(event_id TEXT PRIMARY KEY REFERENCES events,epoch INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sync_fetch_waits(url TEXT PRIMARY KEY REFERENCES sep_urls,reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_event_holds(event_id TEXT PRIMARY KEY REFERENCES events,reason TEXT NOT NULL,op_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_fact_archive(archive_id TEXT PRIMARY KEY,event_id TEXT REFERENCES events,original_fact_id INTEGER NOT NULL,payload TEXT NOT NULL,op_id TEXT NOT NULL,phase TEXT NOT NULL);
CREATE VIEW IF NOT EXISTS sync_event_review_status AS SELECT event_id,count(*) AS pending_judgments FROM (SELECT d.event_id FROM sync_decisions d JOIN sync_decision_state s USING(decision_id) WHERE s.status='needs_recheck' UNION ALL SELECT event_id FROM sync_event_holds) GROUP BY event_id;
CREATE TABLE IF NOT EXISTS sync_content_heads(event_id TEXT REFERENCES events,url TEXT REFERENCES sep_urls,edition_id TEXT NOT NULL,state_id TEXT REFERENCES sync_source_states,adoption_id TEXT REFERENCES sync_adoptions,PRIMARY KEY(event_id,url));
CREATE TABLE IF NOT EXISTS sync_content_changes(adoption_id TEXT PRIMARY KEY REFERENCES sync_adoptions,before_payload TEXT NOT NULL,after_payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_revision_validations(operation_id TEXT PRIMARY KEY,decision_id TEXT REFERENCES sync_decisions,event_id TEXT REFERENCES events,source_editions TEXT NOT NULL,guard_input_hash TEXT,canonical_after_hash TEXT,guard_outcome TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_revision_requests(request_id TEXT PRIMARY KEY,command_hash TEXT NOT NULL,job_id TEXT REFERENCES sync_jobs,result TEXT,command_payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_content_editions(edition_id TEXT PRIMARY KEY,state_id TEXT REFERENCES sync_source_states,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_revision_transitions(transition_id TEXT PRIMARY KEY,request_id TEXT REFERENCES sync_revision_requests,old_status TEXT,new_status TEXT NOT NULL,at TEXT NOT NULL);
